 string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"WakeFixture");Directory.CreateDirectory(root);try{var t=typeof(RemoteConfig).Assembly.GetType("RockTekRemote");var f=BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic;object runtime=FormatterServices.GetUninitializedObject(t);Action<string,object> set=(n,v)=>t.GetField(n,f).SetValue(runtime,v);var fake=new WakeFake();var config=RemoteConfig.Defaults();config.Buttons["Home"].Action="Key";config.Buttons["Home"].Key="Enter";config.Buttons["Home"].Scope="Everywhere";set("Config",config);set("Clock",Stopwatch.StartNew());set("Repeater",new HoldRepeater());set("LogFile",Path.Combine(root,"test.log"));set("ConfigPath",Path.Combine(root,"settings.json"));set("ActionAdapter",fake);System.Threading.Thread.Sleep(300);var router=Wake();router.RawHome(110);Check(router.Resolve(105,240,true)==2,"adapter correlation accepted");set("WakeHome",router);Action route=()=>{t.GetMethod("RouteWakeHome",f).Invoke(runtime,null);var ex=(ActionExecutor)t.GetField("Executor",f).GetValue(runtime);if(ex!=null)Check(ex.WaitForIdle(1000),"fake worker idle");};route();Check(fake.Calls.Count==1&&fake.Calls[0]=="key:Enter","saved Home action used without hardcoded player");fake.Calls.Clear();t.GetMethod("HandleInput",f).Invoke(runtime,new object[]{ConsumerInput.Target,new RemoteInputEvent{InputType="Consumer",Code=0x223},false});Check(fake.Calls.Count==0,"real Consumer Home duplicate does not execute again");t.GetMethod("HandleInput",f).Invoke(runtime,new object[]{ConsumerInput.Target,new RemoteInputEvent{InputType="Consumer",IsRelease=true},false});foreach(string action in new[]{"Disabled","Native"}){config.Buttons["Home"].Action=action;route();Check(fake.Calls.Count==0,"saved "+action+" obeyed");}config.Buttons["Home"].Action="Key";config.Buttons["Home"].Scope="Application";config.Buttons["Home"].ScopeApplicationPath="wanted.exe";set("ForegroundPath",(Func<string>)(()=>"other.exe"));route();Check(fak